import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    expected_width = 8
    header = None
    for record in reader:
        if len(record) >= expected_width and any(cell.strip() for cell in record):
            header = record
            break

    if header is None:
        return {"columns": [], "rows": []}

    # The width hint is a minimum: retain named fields and populated extras.
    width = expected_width
    for index, name in enumerate(header, start=1):
        if name.strip():
            width = max(width, index)

    rows = []
    for record in reader:
        if not record:
            continue
        rows.append(record)
        for index in range(len(record) - 1, width - 1, -1):
            if record[index] != "":
                width = index + 1
                break

    columns = header[:width] + [""] * max(0, width - len(header))
    used_names = set(columns)
    for index, name in enumerate(columns):
        if not name.strip():
            base = f"column_{index + 1}"
            candidate = base
            suffix = 2
            while candidate in used_names:
                candidate = f"{base}_{suffix}"
                suffix += 1
            columns[index] = candidate
            used_names.add(candidate)

    for record in rows:
        del record[width:]
        record.extend([""] * (width - len(record)))

    return {"columns": columns, "rows": rows}
